import { Bot } from "lucide-react";
import { CopyButton } from "../../../components/CopyButton";
import { Markdown } from "../prompt-kit/markdown";
import { fmtTime } from "./InfoCard";

/** In-context evidence generated by Errandd, rather than an external notification or agent answer. */
export function RepositoryAnalysisMessage({ text, at }: { text: string; at?: number }) {
  const time = fmtTime(at);
  return <section aria-label="Repository pre-analysis" className="my-4 rounded-lg border border-base-300 bg-base-200/40 p-4">
    <header className="mb-3 flex items-center gap-2 text-xs text-base-content/60">
      <Bot className="size-4 shrink-0" aria-hidden="true" />
      <span>Errandd · system context · preliminary lockfile analysis</span>
      {time && <time className="ml-auto shrink-0">{time}</time>}
    </header>
    <div className="relative min-w-0 pr-8">
      <CopyButton text={text} label="repository pre-analysis" />
      <Markdown>{text}</Markdown>
    </div>
  </section>;
}
